/* furn.h - the furniture catalog record and its enums.
 *
 * CONTRACT (docs/design/story/SPEC.md sec.4): written by S0, maintained by H1
 * (add-only). The rows are generated by core/tools/furngen.c (H4) from
 * core/data/furn/catalog.txt (H1: stats) joined with core/data/furn/art/
 * (H4: prims) into core/gen/furn_data.c (the PS1 `home` overlay group) and
 * core/gen/furn_grant.c (resident {unlock -> furn} table, SPEC C3).
 *
 * Ids are append-only and saved as 9 bits (SPEC R9: FURN_MAX 384). Only
 * code inside the home group may touch doomo_furn[] (SPEC C6); story code
 * goes through house_api.h.
 */
#ifndef DOOMO_FURN_H
#define DOOMO_FURN_H

#include "types.h"

#define FURN_MAX   384          /* ids 0..383, 9 bits in the save          */
#define FURN_NONE  0x1FF        /* the 9-bit "no piece"                    */

/* Catalog categories (HF sec.8.1). Append only. */
enum { FCAT_PASTEL, FCAT_GOTHIC, FCAT_HELLISH, FCAT_PLUSH, FCAT_KITCHEN,
       FCAT_TECH, FCAT_GARDEN, FCAT_LIGHT, FCAT_WALL, FCAT_RUG, FCAT_TROPHY,
       FCAT_SEASONAL, FCAT_STORY, FCAT_COUNT };

/* DoomoFurn.flags */
enum { FF_WALL = 1, FF_RUG = 2, FF_SURFACE = 4, FF_SMALL = 8, FF_LIGHT = 16,
       FF_ANIM = 32, FF_HELL = 64, FF_BILLBOARD = 128 };
/* DoomoFurn.flags2 (SPEC sec.4) */
enum { FF_PORTAL = 1,       /* a door: fixed slot, re-skin only            */
       FF_CURSED = 2,       /* tape-stops the vamp when it lands           */
       FF_NO_SQUASH = 4,    /* hell props never wobble (SF sec.15.4)          */
       FF_UNSELLABLE = 8,   /* gifts, trophies, story pieces (cap 1)       */
       FF_GIFT = 16 };      /* placed by a citizen; `giver` is valid       */

/* Interactions (FI_*): what Live mode does with a piece. */
enum { FI_NONE, FI_SIT, FI_SLEEP, FI_EAT, FI_COOK, FI_PLAY, FI_WATCH, FI_MUSIC,
       FI_READ, FI_BATHE, FI_PRAY, FI_SUMMON, FI_EXAMINE, FI_TURRET, FI_COUNT };

/* Themes (HF sec.2.3): each is a 6-byte ROM record in themes.txt (H1). */
enum { THEME_PASTEL, THEME_CLOUD, THEME_CANDY, THEME_COTTAGE, THEME_GOTH,
       THEME_BONE, THEME_LAVA, THEME_VAPOR, THEME_PICNIC, THEME_WORKSHOP,
       THEME_COUNT };
#define THEME_NONE 0xFF

typedef struct DoomoFurn {
    const char *name, *desc;          /* <= 20 / <= 40 chars                       */
    uint16_t price;                   /* H$, 0 = gift / story only                 */
    uint16_t unlock;                  /* unlock id gate (any team's range), 0xFFFF open */
    uint16_t giver;                   /* resident id for FF_GIFT pieces, 0xFFFF none */
    uint8_t  cat, flags, flags2, interact; /* FCAT_*, FF_*, FF_* (flags2), FI_*   */
    uint8_t  fw, fd, fh;              /* footprint tiles 1..4, height px/4          */
    uint8_t  paint_a, paint_b;        /* default paints, 0xFF = fixed               */
    int8_t   cute, spooky, comfy;     /* score contributions                        */
    uint8_t  need;                    /* resident.h STAT_* restored by FI_* use, 0xFF none */
    uint8_t  seat_dz, light_r;        /* seat/sleep offset, lamp radius (tiles)     */
    uint8_t  theme;                   /* THEME_* (for Style / Harmony)              */
    uint8_t  mass;                    /* barricade HP contribution (0 = none)       */
    uint8_t  nprim;                   /* recipe in doomo_furn_prims[]               */
    uint16_t prim0;
    uint8_t  frames;                  /* GBA animation frames                       */
} DoomoFurn;

/* Generated tables (furngen, H4). Weak empty defaults: core/src/stubs.c. */
extern const DoomoFurn doomo_furn[];
extern const uint16_t  doomo_furn_count;

#endif
